27	// assemblyStore is a caller-supplied service.Store written only against the
28	// exported storage contract. It keeps records in memory, can be forced to
29	// fail like any backend, and counts calls so tests can prove that rejected
30	// input never reaches storage.
31	type assemblyStore struct {
32		records []service.Record
33		byID    map[string]int               // repository\x00digest -> records index
34		tags    map[string]map[string]string // repository -> tag -> digest
35		fault   error
36		calls   map[string]int
37	}
38	
39	func newAssemblyStore() *assemblyStore {
40		return &assemblyStore{
41			byID:  make(map[string]int),
42			tags:  make(map[string]map[string]string),
43			calls: make(map[string]int),
44		}
45	}
46	
47	func assemblyID(repository, digest string) string { return repository + "\x00" + digest }
48	
49	func (a *assemblyStore) Register(in service.Record) (service.Record, service.RegisterStatus, error) {
50		a.calls["register"]++
51		if a.fault != nil {
52			return service.Record{}, 0, a.fault
53		}
54		key := assemblyID(in.Repository, in.Digest)
55		if idx, ok := a.byID[key]; ok {
56			existing := a.records[idx]
57			if existing.Tag == in.Tag &&
58				existing.SignatureVerified == in.SignatureVerified &&
59				existing.RetentionDays == in.RetentionDays &&
60				existing.SizeBytes == in.SizeBytes {
61				return existing, service.StatusDuplicate, nil
62			}
63			return service.Record{}, service.StatusConflict, nil
64		}
65		a.byID[key] = len(a.records)
66		a.records = append(a.records, in)
67		if a.tags[in.Repository] == nil {
68			a.tags[in.Repository] = make(map[string]string)
69		}
70		a.tags[in.Repository][in.Tag] = in.Digest
71		return in, service.StatusCreated, nil
72	}
73	
74	func (a *assemblyStore) ListRecords(repository string) ([]service.Record, error) {
75		a.calls["list"]++
76		if a.fault != nil {
77			return nil, a.fault
78		}
79		var out []service.Record
80		for _, record := range a.records {
81			if record.Repository == repository {
82				out = append(out, record)
83			}
84		}
85		return out, nil
86	}
87	
88	func (a *assemblyStore) RecordByDigest(repository, digest string) (service.Record, error) {
89		a.calls["digest"]++
90		if a.fault != nil {
91			return service.Record{}, a.fault
92		}
93		if idx, ok := a.byID[assemblyID(repository, digest)]; ok {
94			return a.records[idx], nil
95		}
96		return service.Record{}, service.ErrRecordNotFound
97	}
98	
99	func (a *assemblyStore) RecordByTag(repository, tag string) (service.Record, error) {
100		a.calls["tag"]++
101		if a.fault != nil {
102			return service.Record{}, a.fault
103		}
104		digest, ok := a.tags[repository][tag]
105		if !ok {
106			return service.Record{}, service.ErrRecordNotFound
107		}
108		return a.records[a.byID[assemblyID(repository, digest)]], nil
109	}
110	
111	func (a *assemblyStore) totalCalls() int {
112		total := 0
113		for _, n := range a.calls {
114			total += n
115		}
116		return total
117	}
